package com.group01.assessment.infrastructure.persistence.adapter; import com.group01.assessment.domain.entity.ItemResult; import com.group01.assessment.domain.repository.ItemResultRepository; import com.group01.assessment.infrastructure.persistence.mapper.AssessmentPersistenceMapper; import com.group01.assessment.infrastructure.persistence.repository.ItemResultJpaRepository; import org.springframework.stereotype.Component; import java.util.*;
@Component public class ItemResultRepositoryAdapter implements ItemResultRepository{private final ItemResultJpaRepository repository;private final AssessmentPersistenceMapper mapper;public ItemResultRepositoryAdapter(ItemResultJpaRepository repository,AssessmentPersistenceMapper mapper){this.repository=repository;this.mapper=mapper;}public List<ItemResult> saveAll(List<ItemResult> v){return repository.saveAll(v.stream().map(mapper::toEntity).toList()).stream().map(mapper::toDomain).toList();}public List<ItemResult> findByResultId(UUID id){return repository.findByResultId(id).stream().map(mapper::toDomain).toList();}}
